    @PUT
    @Authenticated
    @Consumes(MediaTypes.JSON)
    @Schema(request = Schemas.GROUP_MODIFY)
    public Response modify(Group changes) throws ValidationException, IllegalModificationException {
        checkRights(getRights().canModify(this.group));
