public class UpCastingIterable<T> extends Paginated<T> implements Iterable<T> {
    private final Iterable<? extends T> delegate;
    private List<T> items = null;

    public UpCastingIterable(Builder<?, ?, T> builder) {
        super(builder.getPagination(), builder.getElements());
        this.delegate = Preconditions.checkNotNull(builder.getDelegate());
    }

    public Stream<T> stream() {
        return StreamSupport.stream(spliterator(), false);
    }

    @Override
    @SuppressWarnings("unchecked")
    public Iterator<T> iterator() {
        if (items == null) {
            items = new LinkedList<>();
            return new Iterator<T>() {
                private final Iterator<? extends T> it = delegate.iterator();

                @Override
                public boolean hasNext() {
                    return it.hasNext();
                }

                @Override
                public T next() {
                    T t = it.next();
                    items.add(t);
                    return t;
                }

                @Override
                public void remove() {
                    throw new UnsupportedOperationException();
                }
            };
        } else {
            return items.iterator();
        }
    }

    public abstract static class Builder<B extends Builder<B, I, T>, I extends UpCastingIterable<T>, T> {
        private final Iterable<? extends T> delegate;
        private Pagination pagination;
        private long elements;

        public Builder(Iterable<? extends T> delegate) {
            this.delegate = delegate;
        }

        @SuppressWarnings("unchecked")
        public B withPagination(Pagination pagination) {
            this.pagination = pagination;
            return (B) this;
        }

        @SuppressWarnings("unchecked")
        public B withElements(long elements) {
            this.elements = elements;
            return (B) this;
        }

        protected Iterable<? extends T> getDelegate() {
            return delegate;
        }

        protected Pagination getPagination() {
            return pagination;
        }

        protected long getElements() {
            return elements;
        }

        public abstract I build();
    }

    @Override
    public String toString() {
        return Joiner.on(", ").appendTo(new StringBuilder()
                                                .append(getClass().getSimpleName())
                                                .append('['), iterator()).append(']').toString();
    }
}

public class JsonSchemaUriReplacerImpl implements JsonSchemaUriReplacer {
    private final JsonNodeCreator jsonNodeCreator;
    private final JsonSchemaUriConfiguration schemaUriConfiguration;

    @Inject
    public JsonSchemaUriReplacerImpl(JsonNodeCreator jsonNodeCreator,
                                     JsonSchemaUriConfiguration schemaUriConfiguration) {
        this.jsonNodeCreator = jsonNodeCreator;
        this.schemaUriConfiguration = schemaUriConfiguration;
    }

    @Override
    public JsonNode replaceSchemaLinks(JsonNode node) {
        if (node.isObject()) {
            return handleObjectNode(node);
        } else if (node.isArray()) {
            return handleArrayNode(node);
        } else {
            return node;
        }
    }

    private JsonNode handleArrayNode(JsonNode node) {
        ArrayNode arrayNode = this.jsonNodeCreator.arrayNode();
        IntStream.range(0, node.size())
                 .mapToObj(node::path)
                 .map(this::replaceSchemaLinks)
                 .forEachOrdered(arrayNode::add);
        return arrayNode;
    }

    private JsonNode handleObjectNode(JsonNode node) {
        ObjectNode objectNode = this.jsonNodeCreator.objectNode();
        node.fieldNames().forEachRemaining(name -> {
            JsonNode child = node.path(name);
            if ("$ref".equals(name) && child.isTextual()) {
                String textValue = child.textValue();
                try {
                    objectNode.put(name, this.schemaUriConfiguration.toExternalURI(new URI(textValue)).toString());
                } catch (URISyntaxException ignored) {
                    objectNode.set(name, child);
                }
            } else {
                objectNode.set(name, replaceSchemaLinks(child));
            }
        });
        return objectNode;
    }

}

