public abstract class Paginated<T> {
    private final Optional<Pagination> current;
    private final Optional<Pagination> last;
    private final Optional<Pagination> first;
    private final Optional<Pagination> prev;
    private final Optional<Pagination> next;
    private final long elements;

    public Paginated(Pagination current, long elements) {
        this.current = Optional.ofNullable(current);
        this.elements = elements;

        if (this.current.isPresent()) {
            this.last = this.current.get().last(this.elements);
            this.first = this.current.get().first(this.elements);
            this.prev = this.current.get().previous(this.elements);
            this.next = this.current.get().next(this.elements);
        } else {
            Optional<Pagination> absent = Optional.empty();
            this.last = absent;
            this.first = absent;
            this.prev = absent;
            this.next = absent;
        }

    }

    public Optional<Pagination> getLast() {
        return last;
    }

    public Optional<Pagination> getNext() {
        return this.next;
    }

    public Optional<Pagination> getCurrent() {
        return this.current;
    }

    public Optional<Pagination> getPrevious() {
        return this.prev;
    }

    public Optional<Pagination> getFirst() {
        return this.first;
    }

    public boolean isPaginated() {
        return this.current.isPresent();
    }

    public long getTotalCount() {
        return this.elements;
    }

    @Override
    public String toString() {
        return MoreObjects.toStringHelper(this)
                          .add("first", getFirst().orElse(null))
                          .add("previous", getPrevious().orElse(null))
                          .add("current", getCurrent().orElse(null))
                          .add("next", getNext().orElse(null))
                          .add("last", getLast().orElse(null))
                          .toString();
    }
}

public class JsonSchemaUriReplacerImpl implements JsonSchemaUriReplacer {
    private final JsonNodeCreator jsonNodeCreator;
    private final JsonSchemaUriConfiguration schemaUriConfiguration;

    @Inject
    public JsonSchemaUriReplacerImpl(JsonNodeCreator jsonNodeCreator,
                                     JsonSchemaUriConfiguration schemaUriConfiguration) {
        this.jsonNodeCreator = jsonNodeCreator;
        this.schemaUriConfiguration = schemaUriConfiguration;
    }

    @Override
    public JsonNode replaceSchemaLinks(JsonNode node) {
        if (node.isObject()) {
            return handleObjectNode(node);
        } else if (node.isArray()) {
            return handleArrayNode(node);
        } else {
            return node;
        }
    }

    private JsonNode handleArrayNode(JsonNode node) {
        ArrayNode arrayNode = this.jsonNodeCreator.arrayNode();
        IntStream.range(0, node.size())
                 .mapToObj(node::path)
                 .map(this::replaceSchemaLinks)
                 .forEachOrdered(arrayNode::add);
        return arrayNode;
    }

    private JsonNode handleObjectNode(JsonNode node) {
        ObjectNode objectNode = this.jsonNodeCreator.objectNode();
        node.fieldNames().forEachRemaining(name -> {
            JsonNode child = node.path(name);
            if ("$ref".equals(name) && child.isTextual()) {
                String textValue = child.textValue();
                try {
                    objectNode.put(name, this.schemaUriConfiguration.toExternalURI(new URI(textValue)).toString());
                } catch (URISyntaxException ignored) {
                    objectNode.set(name, child);
                }
            } else {
                objectNode.set(name, replaceSchemaLinks(child));
            }
        });
        return objectNode;
    }

}

