        this.value = value;
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(this.field, this.value);
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == null) {
            return false;
        }
        if (getClass() != obj.getClass()) {
            return false;
        }
