public class JsonSchemaFactoryProvider implements Provider<JsonSchemaFactory> {

    @Override
    public JsonSchemaFactory get() {
        JsonSchemaFactory factory = JsonSchemaFactory.newBuilder()
                .setValidationConfiguration(validationConfiguration())
                .setLoadingConfiguration(LoadingConfiguration.byDefault().thaw().setEnableCache(true).freeze())
                .freeze();
        return factory;
    }

    private ValidationConfiguration validationConfiguration() {
        Library modifiedV4 = DraftV4Library.get().thaw()
                .addFormatAttribute("date", DateAttribute.getInstance())
                .freeze();
        ValidationConfigurationBuilder vcb = ValidationConfiguration.newBuilder();
        JsonRef ref = JsonRef.fromURI(SchemaVersion.DRAFTV4.getLocation());
        /*
         * FIXME ugliest hack ever. consider to duplicate the v4 schema under a
         * different URI and to adjust the schema files with that URI
         */
        setLibrary(vcb, ref, modifiedV4);
        setDefaultLibrary(vcb, modifiedV4);
        return vcb.freeze();
    }

    @SuppressWarnings("unchecked")
    private void setLibrary(ValidationConfigurationBuilder vcb, JsonRef ref, Library lib) {
        try {
            Field librariesField = ValidationConfigurationBuilder.class.getDeclaredField("libraries");
            librariesField.setAccessible(true);
            final Map<JsonRef, Library> libraries = (Map<JsonRef, Library>) librariesField.get(vcb);
            libraries.put(ref, lib);
            librariesField.setAccessible(false);
        } catch (NoSuchFieldException | SecurityException | IllegalArgumentException | IllegalAccessException ex) {
            throw new RuntimeException(ex);
        }
    }

    private void setDefaultLibrary(ValidationConfigurationBuilder vcb, Library lib) {
        try {
            Field defaultLibraryField = ValidationConfigurationBuilder.class.getDeclaredField("defaultLibrary");

            defaultLibraryField.setAccessible(true);
            defaultLibraryField.set(vcb, lib);
            defaultLibraryField.setAccessible(false);
        } catch (NoSuchFieldException | SecurityException | IllegalArgumentException | IllegalAccessException ex) {
            throw new RuntimeException(ex);
        }
    }
}

@Singleton
public class JsonSchemaUriLoaderImpl implements JsonSchemaUriLoader {
    private final LoadingCache<URI, JsonNode> jsonCache = jsonCache();
    private final JsonSchemaUriConfiguration jsonSchemaUriConfiguration;

    @Inject
    public JsonSchemaUriLoaderImpl(JsonSchemaUriConfiguration jsonSchemaUriConfiguration) {
        this.jsonSchemaUriConfiguration = jsonSchemaUriConfiguration;
    }

    @Override
    public JsonNode load(URI uri) throws IOException {
        try {
            return this.jsonCache.get(uri);
        } catch (ExecutionException e) {
            throw new IOException(e);
        }
    }

    private JsonNode loadInternal(URI key) throws IOException {
        URI uri = this.jsonSchemaUriConfiguration.toInternalURI(key);
        if (uri == null) {
            throw new FileNotFoundException();
        }
        return JsonLoader.fromURL(uri.toURL());
    }

    private LoadingCache<URI, JsonNode> jsonCache() {
        return CacheBuilder.newBuilder().build(new CacheLoader<URI, JsonNode>() {
            @Override
            public JsonNode load(URI key) throws IOException {
                return loadInternal(key);
            }
        });
    }

}

public abstract class Paginated<T> {
    private final Optional<Pagination> current;
    private final Optional<Pagination> last;
    private final Optional<Pagination> first;
    private final Optional<Pagination> prev;
    private final Optional<Pagination> next;
    private final long elements;

    public Paginated(Pagination current, long elements) {
        this.current = Optional.ofNullable(current);
        this.elements = elements;

        if (this.current.isPresent()) {
            this.last = this.current.get().last(this.elements);
            this.first = this.current.get().first(this.elements);
            this.prev = this.current.get().previous(this.elements);
            this.next = this.current.get().next(this.elements);
        } else {
            Optional<Pagination> absent = Optional.empty();
            this.last = absent;
            this.first = absent;
            this.prev = absent;
            this.next = absent;
        }

    }

    public Optional<Pagination> getLast() {
        return last;
    }

    public Optional<Pagination> getNext() {
        return this.next;
    }

    public Optional<Pagination> getCurrent() {
        return this.current;
    }

    public Optional<Pagination> getPrevious() {
        return this.prev;
    }

    public Optional<Pagination> getFirst() {
        return this.first;
    }

    public boolean isPaginated() {
        return this.current.isPresent();
    }

    public long getTotalCount() {
        return this.elements;
    }

    @Override
    public String toString() {
        return MoreObjects.toStringHelper(this)
                          .add("first", getFirst().orElse(null))
                          .add("previous", getPrevious().orElse(null))
                          .add("current", getCurrent().orElse(null))
                          .add("next", getNext().orElse(null))
                          .add("last", getLast().orElse(null))
                          .toString();
    }
}

@ImplementedBy(JsonSchemaUriConfigurationImpl.class)
public interface JsonSchemaUriConfiguration {
    /**
     * Convert the schema {@link URI} to its external form.
     *
     * @param uri The internal URI.
     * @return The external URI.
     */
    URI toExternalURI(URI uri);

    /**
     * Convert the schema {@link URI} to its internal URI.
     *
     * @param uri The internal URI.
     * @return The resource URI.
     */
    URI toInternalURI(URI uri);

    default boolean isSchema(MediaType mediaType, String schema) {
        return schema != null && !schema.isEmpty() &&
                MediaTypes.getSchemaAttribute(mediaType)
                        .map(URI::create)
                        .map(URI::getPath)
                        .map(path -> path.split("/"))
                        .filter(path -> path.length > 0)
                        .map(path -> path[path.length - 1])
                        .map(schema::equals)
                        .orElse(false);
    }
}

public class JsonSchemaUriConfigurationImpl implements JsonSchemaUriConfiguration {
    private final Provider<UriInfo> uriInfo;

    @Inject
    public JsonSchemaUriConfigurationImpl(Provider<UriInfo> uriInfo) {
        this.uriInfo = uriInfo;
    }

    @Override
    public URI toExternalURI(URI uri) {
        if (uri.isAbsolute() || uri.getScheme() != null || uri.getPath().isEmpty()) {
            return uri;
        }

        String path = uri.getPath().endsWith(".json")
                      ? uri.getPath().substring(0, uri.getPath().length() - ".json".length())
                      : uri.getPath();

        path = Paths.get(path).getFileName().toString();

        return this.uriInfo.get()
                           .getBaseUriBuilder()
                           .path(RootResource.SCHEMAS)
                           .path(JsonSchemaResource.SCHEMA)
                           .fragment(uri.getFragment())
                           .build(path);
    }

    @Override
    public URI toInternalURI(URI uri) {
        if (uri.isAbsolute() || uri.getScheme() != null || uri.getPath().isEmpty()) {
            return uri;
        }
        String resourceName = String.format("/schema/%s.json", uri.getPath());
        URL resource = JsonSchemaUriConfigurationImpl.class.getResource(resourceName);
        if (resource != null) {
            try {
                return resource.toURI();
            } catch (URISyntaxException ignored) {
            }
        }
        return null;
    }

}

