public class BoundingBox {
    public static final int MIN_Y = -90;
    public static final int MAX_Y = 90;
    public static final int MIN_X = -180;
    public static final int MAX_X = 180;
    private final Coordinate lowerleft;
    private final Coordinate lowerRight;
    private final Coordinate upperRight;
    private final Coordinate upperLeft;

    public BoundingBox(double minx, double miny, double maxx, double maxy) {
        validate(miny, maxy, minx, maxx);
        this.upperRight = new Coordinate(maxx, maxy);
        this.upperLeft = new Coordinate(minx, maxy);
        this.lowerRight = new Coordinate(maxx, miny);
        this.lowerleft = new Coordinate(minx, miny);
    }

    public Coordinate[] asCoordinates() {
        return new Coordinate[]{
                lowerLeft(),
                lowerRight(),
                upperRight(),
                upperLeft(),
                lowerLeft()
        };
    }

    public Polygon asPolygon(GeometryFactory factory) {
        return factory.createPolygon(asCoordinates());
    }

    protected Coordinate lowerLeft() {
        return lowerleft;
    }

    protected Coordinate lowerRight() {
        return lowerRight;
    }

    protected Coordinate upperRight() {
        return upperRight;
    }

    protected Coordinate upperLeft() {
        return upperLeft;
    }

    public static BoundingBox valueOf(String bbox) {
        final String[] coords = bbox.split(",");
        if (coords.length != 4) {
            throw new BadRequestException("invalid number of coordinates");
        }
        try {
            double minx = Double.parseDouble(coords[0]);
            double miny = Double.parseDouble(coords[1]);
            double maxx = Double.parseDouble(coords[2]);
            double maxy = Double.parseDouble(coords[3]);
            return new BoundingBox(minx, miny, maxx, maxy);
        } catch (IllegalArgumentException e) {
            throw new BadRequestException(e);
        }
    }

    private void validate(double miny, double maxy, double minx, double maxx) {
        checkArgument(Double.compare(miny, MAX_Y) <= 0 && Double.compare(miny, MIN_Y) >= 0,
                "Not in bounds (%s <= val <= %s)", MIN_Y, MAX_Y);
        checkArgument(Double.compare(maxy, MAX_Y) <= 0 && Double.compare(maxy, MIN_Y) >= 0,
                "Not in bounds (%s <= val <= %s)", MIN_Y, MAX_Y);
        checkArgument(Double.compare(minx, MAX_X) <= 0 && Double.compare(minx, MIN_X) >= 0,
                "Not in bounds (%s <= val <= %s)", MIN_X, MAX_X);
        checkArgument(Double.compare(maxx, MAX_X) <= 0 && Double.compare(maxx, MIN_X) >= 0,
                "Not in bounds (%s <= val <= %s)", MIN_X, MAX_X);
        checkArgument(Double.compare(minx, maxx) < 0, "maxx <= minx");
        checkArgument(Double.compare(miny, maxy) < 0, "maxy <= miny");
    }
}

public interface MediaTypes {
    String JSON = MediaType.APPLICATION_JSON;
    String XML_RDF = "application/rdf+xml";
    String TURTLE = "text/turtle";
    String CSV = "text/csv";
    String TURTLE_ALT = "application/x-turtle";
    String JPEG = "image/jpeg";
    String PNG = "image/png";
    String YAML = "text/yaml";
    String APPLICATION_ZIPPED_SHP = "application/x-zipped-shp";
    String APPLICATION_X_SHAPEFILE = "application/x-shapefile";

    MediaType JSON_TYPE = MediaType.APPLICATION_JSON_TYPE;
    MediaType YAML_TYPE = MediaType.valueOf(YAML);
    MediaType XML_RDF_TYPE = MediaType.valueOf(XML_RDF);
    MediaType APPLICATION_ZIPPED_SHP_TYPE = MediaType.valueOf(APPLICATION_ZIPPED_SHP);
    MediaType APPLICATION_X_SHAPEFILE_TYPE = MediaType.valueOf(APPLICATION_X_SHAPEFILE);
    MediaType CSV_TYPE = MediaType.valueOf(CSV);
    MediaType TURTLE_TYPE = MediaType.valueOf(TURTLE);
    MediaType TURTLE_ALT_TYPE = MediaType.valueOf(TURTLE_ALT);
    MediaType JSON_EXCEPTION_TYPE = jsonWithSchema(Schemas.EXCEPTION);
    MediaType YAML_EXCEPTION_TYPE = yamlWithSchema(Schemas.EXCEPTION);

    String SCHEMA_ATTRIBUTE = "schema";

    static Map<String, String> schema(String schema) {
        return Collections.singletonMap(SCHEMA_ATTRIBUTE, schema);
    }

    static MediaType jsonWithSchema(String schema) {
        return new MediaType(JSON_TYPE.getType(), JSON_TYPE.getSubtype(), schema(schema));
    }

    static MediaType yamlWithSchema(String schema) {
        return new MediaType(YAML_TYPE.getType(), YAML_TYPE.getSubtype(), schema(schema));
    }

    static boolean hasSchemaAttribute(MediaType mediaType) {
        return mediaType != null
               && (mediaType.isCompatible(JSON_TYPE) || mediaType.isCompatible(YAML_TYPE))
               && mediaType.getParameters().containsKey(SCHEMA_ATTRIBUTE);
    }

    static Optional<String> getSchemaAttribute(MediaType mediaType) {
        return Optional.ofNullable(mediaType)
                       .filter(MediaTypes::hasSchemaAttribute)
                       .map(MediaType::getParameters)
                       .map(m -> m.get(SCHEMA_ATTRIBUTE));
    }

}

