public class MeasurementsResource extends AbstractResource {
    public static final String MEASUREMENT = "{measurement}";
    private final Track track;
    private final User user;
    private final GeometryFactory geometryFactory;

    @Inject
    public MeasurementsResource(@Assisted @Nullable Track track,
                                @Assisted @Nullable User user,
                                GeometryFactory geometryFactory) {
        this.track = track;
        this.user = user;
        this.geometryFactory = geometryFactory;
    }

    @GET
    @Schema(response = Schemas.MEASUREMENTS)
    public Measurements get(@QueryParam(RESTConstants.BBOX) BoundingBox bbox,
                            @QueryParam(RESTConstants.NEAR_POINT) NearPoint nearPoint) throws BadRequestException {
        //check spatial filter
        SpatialFilter sf = null;
        if (bbox != null && nearPoint != null) {
            throw new InvalidParameterException("Only one spatial filter can be applied!");
        } else if (bbox != null) {
            sf = SpatialFilter.bbox(bbox.asPolygon(this.geometryFactory));
        } else if (nearPoint != null) {
            sf = SpatialFilter.nearPoint(nearPoint.getPoint(), nearPoint.getDistance());
        }

        return getDataService()
                .getMeasurements(new MeasurementFilter(this.track, this.user, sf,
                                                       parseTemporalFilterForInstant(),
                                                       getPagination()));
    }

    @POST
    @Authenticated
    @Schema(request = Schemas.MEASUREMENT_CREATE)
    @Consumes(MediaTypes.JSON)
    public Response create(Measurement measurement) throws ValidationException {
        Measurement m;
        if (this.track != null) {
            checkRights(getRights().canModify(this.track));
            measurement.setUser(getCurrentUser());
            m = getDataService().createMeasurement(this.track, measurement);
        } else {
            measurement.setUser(getCurrentUser());
            m = getDataService().createMeasurement(measurement);
        }
        return Response.created(getUriInfo().getAbsolutePathBuilder().path(m.getIdentifier()).build()).build();
    }

    @Path(MEASUREMENT)
    public MeasurementResource measurement(@PathParam("measurement") String id)
            throws MeasurementNotFoundException {
        if (this.user != null) {
            checkRights(getRights().canSeeMeasurementsOf(this.user));
        }
        if (this.track != null) {
            checkRights(getRights().canSeeMeasurementsOf(this.track));
        }

        Measurement m = getDataService().getMeasurement(id);
        checkRights(getRights().canSee(m));
        return getResourceFactory().createMeasurementResource(m, this.user, this.track);
    }
}

public class SensorsResource extends AbstractResource {

    public static final String SENSOR = "{sensor}";
    private final User user;

    @AssistedInject
    public SensorsResource(@Assisted User user) {
        this.user = user;
    }

    @AssistedInject
    public SensorsResource() {
        this(null);
    }

    @GET
    @Schema(response = Schemas.SENSORS)
    public Sensors get(@QueryParam(RESTConstants.TYPE) String type) throws BadRequestException {
        MultivaluedMap<String, String> queryParameters = getUriInfo().getQueryParameters();
        Set<PropertyFilter> filters = Sets.newHashSet();
        for (String key : queryParameters.keySet()) {
            if (key.equals(RESTConstants.LIMIT) || key.equals(RESTConstants.PAGE) || key.equals(RESTConstants.TYPE)) {
                continue;
            }
            List<String> list = queryParameters.get(key);
            for (String value : list) {
                filters.add(new PropertyFilter(key, value));
            }
        }
        return getDataService().getSensors(new SensorFilter(type, this.user, filters, getPagination()));
    }

    @POST
    @Consumes(MediaTypes.JSON)
    @Schema(request = Schemas.SENSOR_CREATE)
    @Authenticated
    public Response create(Sensor sensor) {
        sensor = getDataService().createSensor(sensor);
        return Response.created(getUriInfo().getAbsolutePathBuilder().path(sensor.getIdentifier()).build()).build();
    }

    @Path(SENSOR)
    public SensorResource sensor(@PathParam("sensor") String id) throws SensorNotFoundException {
        Sensor sensor = getDataService().getSensorByName(id);
        checkRights(getRights().canSee(sensor));
        return getResourceFactory().createSensorResource(sensor);
    }
}

