public class UpCastingIterable<T> extends Paginated<T> implements Iterable<T> {
    private final Iterable<? extends T> delegate;
    private List<T> items = null;

    public UpCastingIterable(Builder<?, ?, T> builder) {
        super(builder.getPagination(), builder.getElements());
        this.delegate = Preconditions.checkNotNull(builder.getDelegate());
    }

    public Stream<T> stream() {
        return StreamSupport.stream(spliterator(), false);
    }

    @Override
    @SuppressWarnings("unchecked")
    public Iterator<T> iterator() {
        if (items == null) {
            items = new LinkedList<>();
            return new Iterator<T>() {
                private final Iterator<? extends T> it = delegate.iterator();

                @Override
                public boolean hasNext() {
                    return it.hasNext();
                }

                @Override
                public T next() {
                    T t = it.next();
                    items.add(t);
                    return t;
                }

                @Override
                public void remove() {
                    throw new UnsupportedOperationException();
                }
            };
        } else {
            return items.iterator();
        }
    }

    public abstract static class Builder<B extends Builder<B, I, T>, I extends UpCastingIterable<T>, T> {
        private final Iterable<? extends T> delegate;
        private Pagination pagination;
        private long elements;

        public Builder(Iterable<? extends T> delegate) {
            this.delegate = delegate;
        }

        @SuppressWarnings("unchecked")
        public B withPagination(Pagination pagination) {
            this.pagination = pagination;
            return (B) this;
        }

        @SuppressWarnings("unchecked")
        public B withElements(long elements) {
            this.elements = elements;
            return (B) this;
        }

        protected Iterable<? extends T> getDelegate() {
            return delegate;
        }

        protected Pagination getPagination() {
            return pagination;
        }

        protected long getElements() {
            return elements;
        }

        public abstract I build();
    }

    @Override
    public String toString() {
        return Joiner.on(", ").appendTo(new StringBuilder()
                                                .append(getClass().getSimpleName())
                                                .append('['), iterator()).append(']').toString();
    }
}

public class DimensionedNumber extends Number {
    private static final long serialVersionUID = 1L;
    private final BigDecimal value;
    private final String unit;

    /**
     * Creates a new {@code DimensionedNumber} for the specified value and unit.
     *
     * @param value the value
     * @param unit  the unit
     */
    public DimensionedNumber(BigDecimal value, String unit) {
        this.value = Preconditions.checkNotNull(value);
        this.unit = Preconditions.checkNotNull(Strings.emptyToNull(unit));
    }

    /**
     * Gets the underlying value of this {@code DimensionedNumber}.
     *
     * @return the value
     */
    public BigDecimal value() {
        return this.value;
    }

    /**
     * Gets the unit of this {@code DimensionedNumber}.
     *
     * @return the unit
     */
    public String unit() {
        return this.unit;
    }

    @Override
    public int intValue() {
        return value().intValue();
    }

    @Override
    public long longValue() {
        return value().longValue();
    }

    @Override
    public float floatValue() {
        return value().floatValue();
    }

    @Override
    public double doubleValue() {
        return value().doubleValue();
    }

    @Override
    public String toString() {
        return MoreObjects.toStringHelper(this)
                .add("value", this.value())
                .add("unit", this.unit())
                .toString();
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(value(), unit());
    }

    @Override
    public boolean equals(Object obj) {
        if (obj != null && obj.getClass() == getClass()) {
            DimensionedNumber that = (DimensionedNumber) obj;
            return Objects.equal(this.value(), that.value()) &&
                   Objects.equal(this.unit(), that.unit());
        }
        return false;
    }

}

