public class JsonSchemaFactoryProvider implements Provider<JsonSchemaFactory> {

    @Override
    public JsonSchemaFactory get() {
        JsonSchemaFactory factory = JsonSchemaFactory.newBuilder()
                .setValidationConfiguration(validationConfiguration())
                .setLoadingConfiguration(LoadingConfiguration.byDefault().thaw().setEnableCache(true).freeze())
                .freeze();
        return factory;
    }

    private ValidationConfiguration validationConfiguration() {
        Library modifiedV4 = DraftV4Library.get().thaw()
                .addFormatAttribute("date", DateAttribute.getInstance())
                .freeze();
        ValidationConfigurationBuilder vcb = ValidationConfiguration.newBuilder();
        JsonRef ref = JsonRef.fromURI(SchemaVersion.DRAFTV4.getLocation());
        /*
         * FIXME ugliest hack ever. consider to duplicate the v4 schema under a
         * different URI and to adjust the schema files with that URI
         */
        setLibrary(vcb, ref, modifiedV4);
        setDefaultLibrary(vcb, modifiedV4);
        return vcb.freeze();
    }

    @SuppressWarnings("unchecked")
    private void setLibrary(ValidationConfigurationBuilder vcb, JsonRef ref, Library lib) {
        try {
            Field librariesField = ValidationConfigurationBuilder.class.getDeclaredField("libraries");
            librariesField.setAccessible(true);
            final Map<JsonRef, Library> libraries = (Map<JsonRef, Library>) librariesField.get(vcb);
            libraries.put(ref, lib);
            librariesField.setAccessible(false);
        } catch (NoSuchFieldException | SecurityException | IllegalArgumentException | IllegalAccessException ex) {
            throw new RuntimeException(ex);
        }
    }

    private void setDefaultLibrary(ValidationConfigurationBuilder vcb, Library lib) {
        try {
            Field defaultLibraryField = ValidationConfigurationBuilder.class.getDeclaredField("defaultLibrary");

            defaultLibraryField.setAccessible(true);
            defaultLibraryField.set(vcb, lib);
            defaultLibraryField.setAccessible(false);
        } catch (NoSuchFieldException | SecurityException | IllegalArgumentException | IllegalAccessException ex) {
            throw new RuntimeException(ex);
        }
    }
}

@Singleton
public class JsonSchemaUriLoaderImpl implements JsonSchemaUriLoader {
    private final LoadingCache<URI, JsonNode> jsonCache = jsonCache();
    private final JsonSchemaUriConfiguration jsonSchemaUriConfiguration;

    @Inject
    public JsonSchemaUriLoaderImpl(JsonSchemaUriConfiguration jsonSchemaUriConfiguration) {
        this.jsonSchemaUriConfiguration = jsonSchemaUriConfiguration;
    }

    @Override
    public JsonNode load(URI uri) throws IOException {
        try {
            return this.jsonCache.get(uri);
        } catch (ExecutionException e) {
            throw new IOException(e);
        }
    }

    private JsonNode loadInternal(URI key) throws IOException {
        URI uri = this.jsonSchemaUriConfiguration.toInternalURI(key);
        if (uri == null) {
            throw new FileNotFoundException();
        }
        return JsonLoader.fromURL(uri.toURL());
    }

    private LoadingCache<URI, JsonNode> jsonCache() {
        return CacheBuilder.newBuilder().build(new CacheLoader<URI, JsonNode>() {
            @Override
            public JsonNode load(URI key) throws IOException {
                return loadInternal(key);
            }
        });
    }

}

public abstract class Paginated<T> {
    private final Optional<Pagination> current;
    private final Optional<Pagination> last;
    private final Optional<Pagination> first;
    private final Optional<Pagination> prev;
    private final Optional<Pagination> next;
    private final long elements;

    public Paginated(Pagination current, long elements) {
        this.current = Optional.ofNullable(current);
        this.elements = elements;

        if (this.current.isPresent()) {
            this.last = this.current.get().last(this.elements);
            this.first = this.current.get().first(this.elements);
            this.prev = this.current.get().previous(this.elements);
            this.next = this.current.get().next(this.elements);
        } else {
            Optional<Pagination> absent = Optional.empty();
            this.last = absent;
            this.first = absent;
            this.prev = absent;
            this.next = absent;
        }

    }

    public Optional<Pagination> getLast() {
        return last;
    }

    public Optional<Pagination> getNext() {
        return this.next;
    }

    public Optional<Pagination> getCurrent() {
        return this.current;
    }

    public Optional<Pagination> getPrevious() {
        return this.prev;
    }

    public Optional<Pagination> getFirst() {
        return this.first;
    }

    public boolean isPaginated() {
        return this.current.isPresent();
    }

    public long getTotalCount() {
        return this.elements;
    }

    @Override
    public String toString() {
        return MoreObjects.toStringHelper(this)
                          .add("first", getFirst().orElse(null))
                          .add("previous", getPrevious().orElse(null))
                          .add("current", getCurrent().orElse(null))
                          .add("next", getNext().orElse(null))
                          .add("last", getLast().orElse(null))
                          .toString();
    }
}

@ImplementedBy(JsonSchemaUriConfigurationImpl.class)
public interface JsonSchemaUriConfiguration {
    /**
     * Convert the schema {@link URI} to its external form.
     *
     * @param uri The internal URI.
     * @return The external URI.
     */
    URI toExternalURI(URI uri);

    /**
     * Convert the schema {@link URI} to its internal URI.
     *
     * @param uri The internal URI.
     * @return The resource URI.
     */
    URI toInternalURI(URI uri);

    default boolean isSchema(MediaType mediaType, String schema) {
        return schema != null && !schema.isEmpty() &&
                MediaTypes.getSchemaAttribute(mediaType)
                        .map(URI::create)
                        .map(URI::getPath)
                        .map(path -> path.split("/"))
                        .filter(path -> path.length > 0)
                        .map(path -> path[path.length - 1])
                        .map(schema::equals)
                        .orElse(false);
    }
}

public class JsonSchemaUriConfigurationImpl implements JsonSchemaUriConfiguration {
    private final Provider<UriInfo> uriInfo;

    @Inject
    public JsonSchemaUriConfigurationImpl(Provider<UriInfo> uriInfo) {
        this.uriInfo = uriInfo;
    }

    @Override
    public URI toExternalURI(URI uri) {
        if (uri.isAbsolute() || uri.getScheme() != null || uri.getPath().isEmpty()) {
            return uri;
        }

        String path = uri.getPath().endsWith(".json")
                      ? uri.getPath().substring(0, uri.getPath().length() - ".json".length())
                      : uri.getPath();

        path = Paths.get(path).getFileName().toString();

        return this.uriInfo.get()
                           .getBaseUriBuilder()
                           .path(RootResource.SCHEMAS)
                           .path(JsonSchemaResource.SCHEMA)
                           .fragment(uri.getFragment())
                           .build(path);
    }

    @Override
    public URI toInternalURI(URI uri) {
        if (uri.isAbsolute() || uri.getScheme() != null || uri.getPath().isEmpty()) {
            return uri;
        }
        String resourceName = String.format("/schema/%s.json", uri.getPath());
        URL resource = JsonSchemaUriConfigurationImpl.class.getResource(resourceName);
        if (resource != null) {
            try {
                return resource.toURI();
            } catch (URISyntaxException ignored) {
            }
        }
        return null;
    }

}

@Path("/")
public class RootResource extends AbstractResource {

    public static final String USERS = "users";
    public static final String GROUPS = "groups";
    public static final String TRACKS = "tracks";
    public static final String PHENOMENONS = "phenomenons";
    public static final String SENSORS = "sensors";
    public static final String MEASUREMENTS = "measurements";
    public static final String STATISTICS = "statistics";
    public static final String TERMS_OF_USE = "termsOfUse";
    public static final String SCHEMAS = "schemas";
    public static final String ANNOUNCEMENTS = "announcements";
    public static final String BADGES = "badges";
    public static final String RESET_PASSWORD = "resetPassword";
    public static final String CONFIRM = "confirm";
    public static final String PRIVACY_STATEMENTS = "privacyStatements";
    public static final String API_DOCS = "api-docs";
    private final JsonNodeFactory factory;
    private final CountService countService;

    @Inject
    public RootResource(JsonNodeFactory factory, CountService countService) {
        this.factory = factory;
        this.countService = countService;
    }

    @GET
    @Schema(response = Schemas.ROOT)
    public JsonNode get() {
        ObjectNode root = this.factory.objectNode();
        if (getRights().canSeeUsers()) {
            root.put(JSONConstants.USERS_KEY, getUriBuilder().path(USERS).build().toString());
        }
        if (getRights().canSeeGroups()) {
            root.put(JSONConstants.GROUPS_KEY, getUriBuilder().path(GROUPS).build().toString());
        }
        if (getRights().canSeeTracks()) {
            root.put(JSONConstants.TRACKS_KEY, getUriBuilder().path(TRACKS).build().toString());
        }
        if (getRights().canSeeSensors()) {
            root.put(JSONConstants.SENSORS_KEY, getUriBuilder().path(SENSORS).build().toString());
        }
        if (getRights().canSeePhenomenons()) {
            root.put(JSONConstants.PHENOMENONS_KEY, getUriBuilder().path(PHENOMENONS).build().toString());
        }
        if (getRights().canSeeMeasurements()) {
            root.put(JSONConstants.MEASUREMENTS_KEY, getUriBuilder().path(MEASUREMENTS).build().toString());
        }
        if (getRights().canSeeStatistics()) {
            root.put(JSONConstants.STATISTICS_KEY, getUriBuilder().path(STATISTICS).build().toString());
        }
        if (getRights().canSeeAnnouncements()) {
            root.put(JSONConstants.ANNOUNCEMENTS_KEY, getUriBuilder().path(ANNOUNCEMENTS).build().toString());
        }
        if (getRights().canSeeBadges()) {
            root.put(JSONConstants.BADGES_KEY, getUriBuilder().path(BADGES).build().toString());
        }

        root.put(JSONConstants.API_DOCS, getUriBuilder().path(API_DOCS).build().toString());
        root.put(JSONConstants.SCHEMAS, getUriBuilder().path(SCHEMAS).build().toString());
        root.put(JSONConstants.PRIVACY_STATEMENTS, getUriBuilder().path(PRIVACY_STATEMENTS).build().toString());
        root.put(JSONConstants.TERMS_OF_USE_KEY, getUriBuilder().path(TERMS_OF_USE).build().toString());

        Counts counts = this.countService.getCounts();

        root.putObject(JSONConstants.COUNTS_KEY)
            .put(JSONConstants.USERS_KEY, counts.getUsers())
            .put(JSONConstants.GROUPS_KEY, counts.getGroups())
            .put(JSONConstants.TRACKS_KEY, counts.getTracks())
            .put(JSONConstants.SENSORS_KEY, counts.getSensors())
            .put(JSONConstants.PHENOMENONS_KEY, counts.getPhenomenons())
            .put(JSONConstants.MEASUREMENTS_KEY, counts.getMeasurements())
            .put(JSONConstants.STATISTICS_KEY, counts.getStatistics())
            .put(JSONConstants.ANNOUNCEMENTS_KEY, counts.getAnnouncements())
            .put(JSONConstants.BADGES_KEY, counts.getBadges())
            .put(JSONConstants.PRIVACY_STATEMENTS, counts.getPrivacyStatements())
            .put(JSONConstants.TERMS_OF_USE_KEY, counts.getTermsOfUses())
            .put(JSONConstants.ACTIVITIES_KEY, counts.getActivities())
            .put(JSONConstants.USERSTATISTIC_KEY, counts.getUserStatistics())
            .put(JSONConstants.FUELINGS, counts.getFuelings());

        return root;
    }

    public UriBuilder getUriBuilder() {
        return getUriInfo().getAbsolutePathBuilder();
    }

    @Path(USERS)
    public UsersResource users() {
        return getResourceFactory().createUsersResource();
    }

    @Path(GROUPS)
    public GroupsResource groups() {
        checkRights(getRights().canSeeGroups());
        return getResourceFactory().createGroupsResource(null);
    }

    @Path(TRACKS)
    public TracksResource tracks() {
        checkRights(getRights().canSeeTracks());
        return getResourceFactory().createTracksResource(null);
    }

    @Path(PHENOMENONS)
    public PhenomenonsResource phenomenons() {
        checkRights(getRights().canSeePhenomenons());
        return getResourceFactory().createPhenomenonsResource();
    }

    @Path(SENSORS)
    public SensorsResource sensors() {
        checkRights(getRights().canSeeSensors());
        return getResourceFactory().createSensorsResource();
    }

    @Path(MEASUREMENTS)
    public MeasurementsResource measurements() {
        checkRights(getRights().canSeeMeasurements());
        return getResourceFactory().createMeasurementsResource(null, null);
    }

    @Path(STATISTICS)
    public StatisticsResource statistics() {
        checkRights(getRights().canSeeStatistics());
        return getResourceFactory().createStatisticsResource();
    }

    @Path(TERMS_OF_USE)
    public TermsOfUseResource termsOfUse() {
        return getResourceFactory().createTermsOfUseResource();
    }

    @Path(SCHEMAS)
    public JsonSchemaResource schemas() {
        return getResourceFactory().createSchemaResource();
    }

    @Path(ANNOUNCEMENTS)
    public AnnouncementsResource announcements() {
        checkRights(getRights().canSeeAnnouncements());
        return getResourceFactory().createAnnouncementsResource();
    }

    @Path(BADGES)
    public BadgesResource badges() {
        checkRights(getRights().canSeeBadges());
        return getResourceFactory().createBadgesResource();
    }

